THOUGHT: The IRC helper uses plain CRLF TCP lines and only requires numeric parsing, so I will add a standalone threaded gateway that validates bearer tokens from the shared SQLite database, emits the exact registration numerics, handles the required harmless commands, detects nick collisions, and closes on QUIT. I will then launch it from `start.sh`.

```mswea_bash_command
cat > /app/irc.py <<'PY'
import socketserver, sqlite3, threading, os, time
DB='/app/data/huddle.db'
nicks=set(); lock=threading.Lock()
def db():
 c=sqlite3.connect(DB); c.row_factory=sqlite3.Row; return c
def valid_token(t):
 try:
  c=db(); r=c.execute('select user_id from tokens where token=?',(t,)).fetchone(); c.close(); return r
 except: return None
class IRC(socketserver.StreamRequestHandler):
 def setup(self):
  super().setup(); self.token=None; self.nick=None; self.user=None; self.registered=False
 def send(self,s): 
  try: self.wfile.write((s+'\r\n').encode()); self.wfile.flush()
  except: pass
 def numeric(self,code,text=''):
  self.send(f':huddle {code} {self.nick or "*"} {text}')
 def register(self):
  if self.registered or not self.token or not self.nick or not self.user:return
  with lock:
   if self.nick in nicks:
    self.numeric('433','Nickname in use'); self.nick=None; return
   nicks.add(self.nick)
  self.registered=True
  for code,text in [('001','Welcome'),('002','Your host is huddle'),('003','This server was created today'),('004','huddle huddle 1 1'),('005','CHANTYPES=# :are supported by this server'),('422','MOTD File is missing')]:
   self.numeric(code,text)
 def handle(self):
  try:
   for raw in self.rfile:
    line=raw.decode(errors='replace').strip()
    if not line: continue
    parts=line.split(' ',2); cmd=parts[0].upper(); rest=parts[1:]
    if cmd=='PASS':
     tok=rest[0] if rest else ''
     if not valid_token(tok):
      self.numeric('464','Password incorrect'); continue
     self.token=tok; self.user=valid_token(tok)['user_id']; self.register()
    elif cmd=='NICK':
     nick=rest[0] if rest else ''
     with lock: taken=nick in nicks and nick!=self.nick
     if taken: self.nick=nick; self.numeric('433','Nickname in use'); self.nick=None
     else: self.nick=nick; self.register()
    elif cmd=='USER':
     self.user=self.user or (rest[0] if rest else 'user'); self.register()
    elif cmd=='PING':
     text=rest[-1] if rest else ''; self.send(f':huddle PONG huddle :{text.lstrip(":")}')
    elif cmd=='QUIT':
     return
    elif cmd in ('PONG','NAMES','WHO','LIST','TOPIC','MODE'):
     if self.registered and cmd=='NAMES':
      channel=rest[0] if rest else '*'
      self.numeric('353',f'= {channel} :{self.nick}')
      self.numeric('366',f'{channel} :End of NAMES list')
     elif self.registered and cmd=='TOPIC':
      self.numeric('331',f'{rest[0] if rest else "*"} :No topic is set')
    elif self.registered:
     self.numeric('421',f'{cmd} :Unknown command')
  finally:
   if self.nick:
    with lock: nicks.discard(self.nick)
class Server(socketserver.ThreadingTCPServer):
 allow_reuse_address=True
try:
 with Server(('0.0.0.0',6667),IRC) as srv: srv.serve_forever()
except OSError:
 while True: time.sleep(60)
